int insert_descending(OrderedArray *list, int value)
{
    if (list->size >= list->capacity) {
        return 0;
    }
    int position = 0;
    while (position < list->size && list->data[position] > value) {
        ++position;
    }
    if (position < list->size && list->data[position] == value) {
        return 0;
    }
    for (int i = list->size; i > position; --i) {
        list->data[i] = list->data[i - 1];
    }
    list->data[position] = value;
    ++list->size;
    return 1;
}

