#include <stdio.h>

#define ORDERED_CAPACITY 128
typedef struct {
    int data[ORDERED_CAPACITY];
    int size;
    int capacity;
} OrderedArray;

/*__STUDENT_CODE__*/

int main(void)
{
    OrderedArray list = {0};
    int value;
    if (scanf("%d%d", &list.capacity, &list.size) != 2) return 2;
    if (list.capacity < 0 || list.capacity > ORDERED_CAPACITY ||
        list.size < 0 || list.size > list.capacity) return 2;
    for (int i = 0; i < list.size; ++i) {
        if (scanf("%d", &list.data[i]) != 1) return 2;
    }
    if (scanf("%d", &value) != 1) return 2;
    int original_capacity = list.capacity;
    int ok = insert_descending(&list, value);
    if ((ok != 0 && ok != 1) || list.capacity != original_capacity ||
        list.size < 0 || list.size > original_capacity) {
        puts("INVALID_STATE");
        return 0;
    }
    printf("%s %d\n", ok ? "OK" : "FAIL", list.size);
    for (int i = 0; i < list.size; ++i) {
        if (i) putchar(' ');
        printf("%d", list.data[i]);
    }
    putchar('\n');
    return 0;
}

