bool insert_descending(std::vector<int>& values, int capacity, int value)
{
    if (values.size() >= static_cast<std::size_t>(capacity)) {
        return false;
    }
    std::size_t position = 0;
    while (position < values.size() && values[position] > value) {
        ++position;
    }
    if (position < values.size() && values[position] == value) {
        return false;
    }
    values.insert(values.begin() + static_cast<std::ptrdiff_t>(position), value);
    return true;
}

